import {mountShell} from '../shared/shell.js?v=0.3.0';
import {escapeHtml as e,downloadText,writeStore} from '../shared/utils.js';
import {PRESETS,uid,createWorkspace,ingredients,combinationCount,mixWorkspace,captureConcept,markdown,validateWorkspace} from './model.js';
mountShell({active:'mixer'});
const KEY='thinking-lab:mixer:v1';
let state,undo=[],promptIndex=0,toastTimer,recoveryRaw=null,savePaused=false,storageNotice='';
let raw=null;try{raw=localStorage.getItem(KEY);}catch{storageNotice='Browser storage is unavailable. Export your work to keep it.';}
try{if(!raw)throw Error();state=JSON.parse(raw);if(!state?.workspaces?.length)throw Error();state.workspaces=state.workspaces.map(validateWorkspace);if(!state.workspaces.some(w=>w.id===state.activeId))state.activeId=state.workspaces[0].id;}catch{if(raw){recoveryRaw=raw;savePaused=true;storageNotice='Saved data could not be read. Saving is paused to preserve it. Download a recovery copy before starting fresh.';}const w=createWorkspace();state={workspaces:[w],activeId:w.id};}
const app=document.querySelector('#app'),dialog=document.querySelector('#editor');
const prompts=['Which ingredient is genuinely changing the idea, and which is just decoration?','What would make this combination awkward? The friction may be the useful part.','Who would this leave out? Try replacing the audience while keeping the mechanism.','What is the smallest version that somebody could actually try tomorrow?','Keep the problem. Borrow a mechanism from a completely different world.','Which dimension have you treated as fixed without noticing?'];
const current=()=>state.workspaces.find(w=>w.id===state.activeId);
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function save(){const ok=!savePaused&&writeStore(KEY,state);document.querySelectorAll('.save-status').forEach(el=>{el.textContent=ok?'Saved in this browser':savePaused?'Saving paused · export to keep work':'Storage unavailable · export to keep work';el.classList.toggle('error',!ok);});return ok;}
function checkpoint(){undo.push(structuredClone(state));if(undo.length>20)undo.shift();}
function change(fn){checkpoint();fn(current());render();save();}
function conceptLabel(c,i){return c.title||`Combination ${i+1}`;}
function render(){const focus=document.activeElement;const restore=app.contains(focus)?{id:focus.id,action:focus.dataset.action,key:focus.dataset.id,dimension:focus.dataset.dimension}:null;const w=current(),active=w.concepts.find(c=>c.id===w.activeConceptId);
 app.innerHTML=`${storageNotice?`<div class="storage-notice" role="status"><span>${e(storageNotice)}</span>${recoveryRaw?'<button class="btn small" data-action="recovery">Download recovery copy</button><button class="btn small" data-action="resume-save">Start fresh</button>':savePaused?'<button class="btn small" data-action="reload">Load latest save</button><button class="btn small" data-action="resume-save">Save this tab instead</button>':''}</div>`:''}<section class="intro"><div><p class="eyebrow">Scaffold 02 · Explore possibilities</p><h1>Possibility mixer</h1><p>Change the ingredients. Keep what intrigues you.<br>Turn an unfamiliar combination into an idea worth trying.</p></div><div class="workspace-tools"><label class="sr-only" for="workspace">Workspace</label><select id="workspace">${state.workspaces.map(x=>`<option value="${e(x.id)}" ${x.id===w.id?'selected':''}>${e(x.title)}</option>`).join('')}</select><button class="btn" data-action="new">+ New workspace</button><button class="btn" data-action="export">Export</button><button class="btn quiet" data-action="undo" ${undo.length?'':'disabled'}>Undo</button><span class="save-status">Saved in this browser</span></div></section>
 <section class="question-panel"><div class="section-label">The question<small>Start here. Or edit as you go.</small></div><div class="question-fields"><label class="sr-only" for="workspace-title">Workspace name</label><input id="workspace-title" class="title-input" maxlength="160" value="${e(w.title)}"><label class="sr-only" for="problem">Your problem or question</label><textarea id="problem" class="problem-input" rows="1" maxlength="12000" placeholder="What would you like to make possible?">${e(w.problem)}</textarea></div></section>
 <section aria-labelledby="space-title"><div class="step-heading"><div><h2 id="space-title">01 / Shape the possibility space</h2><p>Pick ingredients directly, or lock a few and mix the rest. The dimensions are yours to change.</p></div><button class="btn small quiet" data-action="add-axis" ${w.dimensions.length>=8?'disabled':''}>+ Dimension</button></div><div class="dimension-board" style="--columns:${w.dimensions.length}">${w.dimensions.map((d,i)=>`<article class="dimension ${d.locked?'locked':''}"><div class="dimension-top"><div class="dimension-name"><span class="dimension-number">${String(i+1).padStart(2,'0')}</span>${e(d.name)}</div><button class="edit-axis" data-action="edit-axis" data-id="${e(d.id)}" aria-label="Edit ${e(d.name)}">Edit</button></div><div class="option-list" role="group" aria-label="${e(d.name)}">${d.options.map(o=>`<button class="option ${o.id===d.selectedId?'selected':''}" aria-pressed="${o.id===d.selectedId}" data-action="pick" data-dimension="${e(d.id)}" data-id="${e(o.id)}"><span class="option-dot" aria-hidden="true"></span>${e(o.label)}</button>`).join('')}</div><button class="lock" data-action="lock" data-id="${e(d.id)}" aria-pressed="${d.locked}"><span aria-hidden="true">${d.locked?'◆':'◇'}</span>${d.locked?'Locked for mixing':'Keep this ingredient'}</button></article>`).join('')}</div>
 <div class="combination"><div><div class="combo-eyebrow">Your current combination</div><p class="combo-line">${ingredients(w).map(i=>`<b>${e(i.label)}</b>`).join('<span class="divider" aria-hidden="true">/</span>')}</p></div><div class="combo-actions"><button class="btn primary" data-action="mix" ${combinationCount(w,true)<2?'disabled':''}>↻ Mix unlocked</button><button class="btn quiet" data-action="capture">Keep &amp; develop →</button></div></div><div class="space-meta"><span><strong>${combinationCount(w).toLocaleString()}</strong> possible combinations · <strong>${combinationCount(w,true).toLocaleString()}</strong> with these locks</span><span>${w.mixCount} mixes explored · ${w.dimensions.filter(d=>d.locked).length} of ${w.dimensions.length} ingredients locked</span></div></section>
 <section class="develop" aria-labelledby="develop-title"><div class="step-heading"><div><h2 id="develop-title">02 / Give a combination a job</h2><p>A combination is a starting point. Your explanation makes it an idea.</p></div><span class="muted" style="font-size:12px">${w.concepts.length} kept</span></div>${w.concepts.length?`<div class="develop-layout"><div class="concept-list" role="group" aria-label="Kept concepts">${w.concepts.map((c,i)=>`<button class="concept-tab ${c.id===w.activeConceptId?'active':''}" data-action="concept" data-id="${e(c.id)}" aria-pressed="${c.id===w.activeConceptId}"><small>Concept ${String(i+1).padStart(2,'0')}</small><strong>${e(conceptLabel(c,i))}</strong><span>${c.mechanism?'In development':'Ready to develop'}</span></button>`).join('')}</div>${active?conceptEditor(active):''}</div>`:`<div class="empty-develop"><div><h3>Something catches your eye?</h3><p>Keep it, explain how the ingredients work together, then make the smallest test concrete. Kept concepts stay intact when you mix again.</p></div><button class="btn" data-action="capture">Develop this combination →</button></div>`}</section>
 <aside class="provocation"><strong>Try a different angle</strong><span id="provocation-text">${prompts[promptIndex]}</span><button class="btn small quiet" data-action="prompt">Another prompt ↗</button></aside>`;
 const problem=document.querySelector('#problem');problem.style.height='auto';problem.style.height=problem.scrollHeight+'px';
 if(restore){let candidate=restore.id?document.getElementById(restore.id):[...app.querySelectorAll('[data-action]')].find(el=>el.dataset.action===restore.action&&el.dataset.id===restore.key&&el.dataset.dimension===restore.dimension);candidate?.focus({preventScroll:true});}
 save();
}
function conceptEditor(c){return `<div class="concept-editor"><label class="sr-only" for="concept-title">Concept name</label><input class="concept-title" id="concept-title" data-field="title" maxlength="160" value="${e(c.title)}" placeholder="Give this idea a name"><div class="ingredients">${c.ingredients.map(i=>`<span class="ingredient" title="${e(i.dimension)}">${e(i.label)}</span>`).join('')}</div><div class="writing-grid">${[['mechanism','How would it work?','Describe an interaction, not just a category of tool.','Someone could…'],['useful','Why could this help?','What becomes easier to see, decide or do?','This would help because…'],['assumption','What are you assuming?','Name the ingredient that may not fit, or the belief to test.','This depends on…'],['experiment','What is the smallest experiment?','Who tries what, and what would you look for?','Try it with…']].map(([key,label,hint,placeholder])=>`<label>${label}<small>${hint}</small><textarea data-field="${key}" maxlength="12000" placeholder="${placeholder}">${e(c[key])}</textarea></label>`).join('')}</div><div class="editor-bottom"><span>Ingredients are a snapshot. Your edits save automatically.</span><button class="btn small quiet danger" data-action="delete-concept" data-id="${e(c.id)}">Remove concept</button></div></div>`;}
function openDialog(html){dialog.innerHTML=html;dialog.showModal();dialog.querySelector('input,textarea,button')?.focus();}
function axisDialog(id){const w=current(),d=w.dimensions.find(x=>x.id===id);openDialog(`<form id="axis-form"><h2>${d?'Edit dimension':'Add a dimension'}</h2><p>Good dimensions describe different aspects of the idea. Make options concrete enough to spark a response.</p><label>Dimension name<input name="name" maxlength="80" required value="${e(d?.name??'') }" placeholder="For whom?"></label><label>Options · one per line<textarea name="options" required placeholder="A trader\nAn asset manager\nA site operator">${e(d?.options.map(o=>o.label).join('\n')??'')}</textarea></label><p class="dialog-error" hidden></p><div class="actions">${d?`<button type="button" class="btn danger" data-action="remove-axis" data-id="${e(id)}" ${w.dimensions.length<=2?'disabled':''}>Remove dimension</button>`:''}<button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">Save dimension</button></div></form>`);dialog.querySelector('form').addEventListener('submit',event=>{event.preventDefault();const form=new FormData(event.currentTarget),name=String(form.get('name')).trim(),labels=[...new Set(String(form.get('options')).split('\n').map(s=>s.trim()).filter(Boolean))];const error=dialog.querySelector('.dialog-error');if(!name||!labels.length||labels.length>12||labels.some(x=>x.length>120)){error.textContent='Use a name and 1–12 options, each up to 120 characters.';error.hidden=false;return;}change(w=>{const options=labels.map(label=>({id:d?.options.find(o=>o.label===label)?.id??uid(),label}));if(d){const target=w.dimensions.find(x=>x.id===d.id);target.name=name;target.options=options;if(!options.some(o=>o.id===target.selectedId))target.selectedId=options[0].id;}else w.dimensions.push({id:uid(),name,options,selectedId:options[0].id,locked:false});w.history=[];});dialog.close();toast('Possibility space updated.');});}
function newDialog(){openDialog(`<h2>Start a new workspace</h2><p>Your current work stays saved. Choose a starting space, then make it your own.</p><div class="preset-grid">${Object.entries(PRESETS).map(([key,p])=>`<button class="preset-choice" data-action="preset" data-id="${key}"><strong>${e(p.name)}</strong><span>${e(p.problem||'Bring your own question and edit every dimension.')}</span></button>`).join('')}</div><div class="actions"><button class="btn" data-action="import">Import JSON</button><button class="btn" data-action="close">Cancel</button></div>`);}
function exportDialog(){openDialog(`<h2>Take your ideas with you</h2><p>Markdown is ready for your notes. JSON preserves this workspace so you can reopen it here.</p><div class="preset-grid"><button class="preset-choice" data-action="markdown"><strong>Download Markdown</strong><span>The question, dimensions and every developed concept.</span></button><button class="preset-choice" data-action="json"><strong>Download workspace JSON</strong><span>A portable backup with all editable content.</span></button></div><div class="actions"><button class="btn" data-action="import">Import JSON</button><button class="btn" data-action="close">Close</button></div>`);}
async function importWorkspace(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2000000)throw Error('Use a JSON file smaller than 2 MB.');const raw=JSON.parse(await file.text()),w=validateWorkspace(raw.workspace??raw);w.id=uid();checkpoint();state.workspaces.push(w);state.activeId=w.id;dialog.close();render();toast('Workspace imported. Existing work is still saved.');}catch(error){toast(`Could not import: ${error.message}`);}});input.click();}
function act(action,id,button){const w=current();switch(action){case 'recovery':downloadText('possibility-mixer-recovery.json',recoveryRaw,'application/json');break;case 'resume-save':savePaused=false;recoveryRaw=null;storageNotice='';render();toast('This workspace is now saved.');break;case 'reload':location.reload();break;case 'pick':change(w=>{w.dimensions.find(d=>d.id===button.dataset.dimension).selectedId=id;});break;case 'lock':change(w=>{const d=w.dimensions.find(x=>x.id===id);d.locked=!d.locked;});break;case 'mix':{checkpoint();const result=mixWorkspace(w);state.workspaces[state.workspaces.findIndex(x=>x.id===w.id)]=result.workspace;render();toast(result.changed?'A new combination. What could make these ingredients work together?':'Unlock a dimension to mix.');break;}case 'capture':if(w.concepts.length>=100){toast('This workspace has 100 concepts. Export or start a new workspace.');break;}change(w=>{const c=captureConcept(w);w.concepts.push(c);w.activeConceptId=c.id;});document.querySelector('.concept-editor')?.scrollIntoView({behavior:'smooth',block:'center'});document.querySelector('#concept-title')?.focus({preventScroll:true});break;case 'concept':w.activeConceptId=id;render();break;case 'delete-concept':change(w=>{w.concepts=w.concepts.filter(c=>c.id!==id);w.activeConceptId=w.concepts[0]?.id??null;});toast('Concept removed. Undo brings it back.');break;case 'edit-axis':axisDialog(id);break;case 'add-axis':axisDialog();break;case 'remove-axis':change(w=>{w.dimensions=w.dimensions.filter(d=>d.id!==id);w.history=[];});dialog.close();toast('Dimension removed. Undo brings it back.');break;case 'new':newDialog();break;case 'preset':{checkpoint();const next=createWorkspace(id);state.workspaces.push(next);state.activeId=next.id;dialog.close();render();break;}case 'export':exportDialog();break;case 'markdown':downloadText('possibility-mixer.md',markdown(w),'text/markdown;charset=utf-8');toast('Markdown downloaded.');break;case 'json':downloadText('possibility-mixer.json',JSON.stringify({version:1,workspace:w},null,2),'application/json');toast('Workspace downloaded.');break;case 'import':importWorkspace();break;case 'close':dialog.close();break;case 'undo':if(undo.length){state=undo.pop();render();toast('Last change undone.');}break;case 'prompt':promptIndex=(promptIndex+1)%prompts.length;document.querySelector('#provocation-text').textContent=prompts[promptIndex];break;}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button)act(button.dataset.action,button.dataset.id,button);});
app.addEventListener('input',event=>{const w=current(),target=event.target;if(target.id==='problem'){w.problem=target.value;target.style.height='auto';target.style.height=target.scrollHeight+'px';}else if(target.id==='workspace-title'){w.title=target.value;const option=document.querySelector(`#workspace option[value="${w.id}"]`);if(option)option.textContent=w.title||'Untitled workspace';}else if(target.dataset.field){const c=w.concepts.find(x=>x.id===w.activeConceptId);if(c)c[target.dataset.field]=target.value;const tab=document.querySelector('.concept-tab.active');if(tab){tab.querySelector('strong').textContent=c.title||`Combination ${w.concepts.indexOf(c)+1}`;tab.querySelector('span').textContent=c.mechanism?'In development':'Ready to develop';}}save();});
app.addEventListener('change',event=>{if(event.target.id==='workspace'){state.activeId=event.target.value;render();}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();}});
addEventListener('storage',event=>{if(event.key===KEY&&event.newValue!==JSON.stringify(state)){savePaused=true;storageNotice='Another tab changed the saved work. Saving is paused so this tab cannot overwrite it.';render();}});
render();
if(document.modelContext?.registerTool){const controller=new AbortController();const tools=[{name:'read_possibility_workspace',title:'Read possibility workspace',description:'Read the current question, dimensions, selected ingredients and kept concepts.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async(input)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object.');return{content:[{type:'text',text:JSON.stringify(current())}]};}},{name:'mix_possibility_ingredients',title:'Mix unlocked ingredients',description:'Generate a new combination while preserving locked ingredients. This updates the visible workspace.',inputSchema:{type:'object',properties:{},additionalProperties:false},execute:async(input)=>{if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).length)throw new Error('Expected an empty object.');act('mix');return{content:[{type:'text',text:JSON.stringify(ingredients(current()))}]};}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}}addEventListener('pagehide',()=>controller.abort(),{once:true});}
